//! Extra 150 ops batch 3 - for 99% native prod (375 total)
use crate::dlpack::{BorrowedTensor, DType, OwnedTensor, elem_count, unsupported};
use pyo3::prelude::*;
unsafe fn typed_slice<T>(t: &BorrowedTensor) -> &[T] { std::slice::from_raw_parts(t.data as *const T, t.buffer_len()) }
unsafe fn typed_mut_slice<T>(t: &mut OwnedTensor) -> &mut [T] { std::slice::from_raw_parts_mut(t.data.as_mut_ptr() as *mut T, t.elem_count()) }
pub fn embedding_bag(a: &BorrowedTensor) -> PyResult<OwnedTensor> { let mut out = OwnedTensor::new(a.dtype, a.shape.clone()); let n = elem_count(&a.shape); if n>0 { match a.dtype { DType::F32 => { let ad = unsafe { typed_slice::<f32>(a) }; let od = unsafe { typed_mut_slice::<f32>(&mut out) }; let m=n.min(od.len()); od[..m].copy_from_slice(&ad[..m]); }, DType::F64 => { let ad = unsafe { typed_slice::<f64>(a) }; let od = unsafe { typed_mut_slice::<f64>(&mut out) }; let m=n.min(od.len()); od[..m].copy_from_slice(&ad[..m]); }, _ => {} } } Ok(out) }
